#include <chrono>
#include <cmath>
#include <cstdint>
#include <cstdio>
#include <cstdlib>
#include <cstring>
#include <unistd.h>
#include <vector>

#include "common.h"

#define KERNEL_NAME "sgemm"
#define FLOAT_ULP   6

#define HIP_CHECK(_expr)                                                  \
  do {                                                                    \
    hipError_t _err = (_expr);                                            \
